      if(validation.renderingReady)continue;const next={...previous,validation,status:(validation.errors.length?'NEEDS_REVISION':'NEEDS_ASSET') as SlotStatus,error:validation.errors.join('; ')||'Human source approval requires gameplay footage; source-backed text and all model versions preserved'};
