      const candidates=versions.filter(v=>(v.stage===0||v.stage===2)&&v.value),original=candidates[0]?.value as CampaignProposal|undefined,revised=candidates.filter(v=>v.stage===2).at(-1)?.value as CampaignProposal|undefined;
