        const current=await this.knowledge.load(slot.projectId);assertKnowledgeStillApproved(slot.snapshot,current);const content=profile.approvedContent.find(c=>c.id===media.contentBaseId);if(!content?.source.includes('Human-approved source recovery package')||/no gameplay footage/i.test(content.disclaimer??''))throw new Error('Select an explicitly source-approved footage composition');
